"""
    This function carries out the automatic file editing, adjusting lines in
    Tapenade generated code as needed.

    Parameters
    ----------
    linesIn : list of string
        Lines of original source code to be parsed

    Returns
    -------
    linesOut : list of string
        Lines of updated code returned
    """
def editFile(linesIn: Any) -> object {
    iLine = 0;
    linesOut = [];
    while (iLine < len(linesIn)) {
        linesOut.append(linesIn[iLine]);
        iLine += 1;
    }
    return linesOut;
}

"""Returns a binary vector that indicates whether individuals are infected."""
def _infection_indicator(health_states: Any, infected_state_index: Any) -> object {
    return [int((state == infected_state_index)) for state in health_states];
}

"""
    SOPC_DateTime* (the number of 100 nanosecond intervals since January 1, 1601)
    to Python time (the floating point number of seconds since 01/01/1970, see help(time)).
    """
def datetime_to_float(datetime: Any) -> object {
    nsec = datetime[0];
    return ((nsec - 116444736000000000) / 10000000.0);
}

"""Format constructor arguments; returns a list

    arguments: Constructor arguments (list)
    parent: Parent widget (string or unicode)
    id: Widget ID e.g. wxID_ANY
    size: Widget size 'width, height'"""
def format_ctor_arguments(arguments: Any, parent: Any, id: Any, size: Any) -> object {
    vSize = size.split(',');
    for i in range(len(arguments)) {
        if (arguments[i] == '$parent') {
            arguments[i] = parent;
        } elif (arguments[i] == '$id') {
            arguments[i] = id;
        } elif (arguments[i] == '$width') {
            arguments[i] = vSize[0];
        } elif (arguments[i] == '$height') {
            arguments[i] = vSize[1];
        }
    }
    return arguments;
}

