"""Format a list or tuple of regex url patterns into a single path."""
def format_regex_stack(regex_stack: Any) -> object {
    import re;
    formatted = ''.join(regex_stack);
    formatted = re.sub('\([^<]*(<[^>]*>).*?\)', '\\1', formatted);
    formatted = formatted.replace('^$', '/');
    formatted = formatted.replace('^', '/');
    formatted = formatted.replace('?$', '/');
    formatted = formatted.replace('$', '/');
    formatted = formatted.replace('//', '/');
    return formatted;
}

"""
    renvoie la position de la case en fontion du sens des lignes
    """
def position_case_ligne_motif(
    pos_ligne_motif: Any, sens: Any, colonne: Any, ligne: Any
) -> object {
    (x_debut, y_debut) = pos_ligne_motif;
    if (sens == "gauche") {
        x_case = x_debut - (colonne * 25);
    } else {
        x_case = x_debut + (colonne * 25);
    }
    return (x_case, (y_debut + (ligne * 25)));
}

